private static boolean check(int x, int y, int N) {
  if (x == y) {
    return true;
  }
  boolean left = false;
  boolean right = false;
  if (2 * x <= N) {
    left = check(2 * x, y, N);
  }
  if (2 * x + 1 <= N) {
    right = check(2 * x + 1, y, N);
  }
  return left || right;
}

